  eventDefault: { leader: 'Aucune publication dans la fenêtre collectée (calendrier couvert jusqu’au 20 octobre) ; son capex reste le signal à suivre', direct_peer: 'Aucune publication dans la fenêtre collectée (jusqu’au 20 octobre) ; ses conditions de financement et ses renouvellements encadrent ceux d’Oracle', upstream: 'Aucune publication dans la fenêtre collectée (jusqu’au 20 octobre) ; ses commandes précèdent les ouvertures de sites', second_order: 'Aucune publication dans la fenêtre collectée (jusqu’au 20 octobre) ; ses contrats d’énergie et de sites restent à suivre', sector_proxy: 'Panier sans publication propre ; exposé aux résultats de ses grandes pondérations' },
